<?php
declare(strict_types=1);
namespace App\Repositories; use App\Core\Database;
final class CategoryRepository { public function all():array{return Database::connection()->query('SELECT * FROM categories ORDER BY name')->fetchAll();} public function find(int $id):?array{$s=Database::connection()->prepare('SELECT * FROM categories WHERE id=?');$s->execute([$id]);return $s->fetch()?:null;} public function create(array $d):int{$s=Database::connection()->prepare('INSERT INTO categories(name,description,icon,color,status,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),NOW())');$s->execute([$d['name'],$d['description']??null,$d['icon']??'tag',$d['color']??'#3b7ddd',$d['status']??'active']);return (int)Database::connection()->lastInsertId();} public function update(int $id,array $d):void{$s=Database::connection()->prepare('UPDATE categories SET name=?,description=?,icon=?,color=?,status=?,updated_at=NOW() WHERE id=?');$s->execute([$d['name'],$d['description']??null,$d['icon']??'tag',$d['color']??'#3b7ddd',$d['status']??'active',$id]);} public function delete(int $id):void{Database::connection()->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);}}
